import{_ as n,I as a,o as d,c,j as t,a as r,J as o,a4 as i}from"./chunks/framework.Co6Rcm-5.js";const u=JSON.parse('{"title":"训练显存账本与数值稳定","description":"从参数、梯度、优化器状态、激活和临时缓冲拆解训练显存，并理解重计算、混合精度与稳定性保障的真实边界。","frontmatter":{"title":"训练显存账本与数值稳定","description":"从参数、梯度、优化器状态、激活和临时缓冲拆解训练显存，并理解重计算、混合精度与稳定性保障的真实边界。"},"headers":[],"relativePath":"ai-infra/training-memory-numerics.md","filePath":"ai-infra/training-memory-numerics.md","lastUpdated":1786522313000}'),p={name:"ai-infra/training-memory-numerics.md"};function h(m,e,g,P,b,f){const l=a("CapacityLab"),s=a("TradeoffExplorer");return d(),c("div",null,[e[0]||(e[0]=t("h1",{id:"训练显存账本与数值稳定",tabindex:"-1"},[r("训练显存账本与数值稳定 "),t("a",{class:"header-anchor",href:"#训练显存账本与数值稳定","aria-label":"Permalink to “训练显存账本与数值稳定”"},"​")],-1)),e[1]||(e[1]=t("p",null,"大模型训练中两个最常见的误判是：“参数能放下，训练就能放下”和“换成 16 位，显存就减半”。训练需要保存参数、梯度、优化器状态、激活、通信缓冲和算子 workspace；混合精度还可能保留 FP32 主权重。显存优化也会改变计算量、通信量和数值路径。可靠的容量规划必须先建立逐项账本，再讨论技术组合。",-1)),e[2]||(e[2]=t("p",null,[r("本文把显存分为五本账："),t("strong",null,"模型状态、保存激活、临时张量、通信缓冲、分配器与框架开销"),r("。账本中的理论值是下界，真实峰值由这些对象的生命周期重叠决定。OOM 发生在峰值时刻，而不是平均时刻。")],-1)),o(l,{preset:"training-memory"}),e[3]||(e[3]=i('<h2 id="参数量只是起点" tabindex="-1">参数量只是起点 <a class="header-anchor" href="#参数量只是起点" aria-label="Permalink to “参数量只是起点”">​</a></h2><p>设模型有 <code>P</code> 个可训练参数，单个数据元素占 <code>b</code> 字节。只做前向时，权重下界约为 <code>P × b</code>；训练时还要加入梯度和优化器状态。以常见的 Adam/AdamW 混合精度训练为例，一种典型但并非唯一的布局是：</p><table tabindex="0"><thead><tr><th>项目</th><th style="text-align:right;">每参数典型字节数</th><th>说明</th></tr></thead><tbody><tr><td>BF16/FP16 模型权重</td><td style="text-align:right;">2</td><td>前向和反向使用的低精度权重</td></tr><tr><td>低精度或 FP32 梯度</td><td style="text-align:right;">2 或 4</td><td>取决于框架、通信与累积策略</td></tr><tr><td>FP32 主权重</td><td style="text-align:right;">4</td><td>用于保留小幅参数更新，部分 BF16 路径可采用不同实现</td></tr><tr><td>Adam 一阶矩</td><td style="text-align:right;">4</td><td><code>m</code></td></tr><tr><td>Adam 二阶矩</td><td style="text-align:right;">4</td><td><code>v</code></td></tr><tr><td>合计</td><td style="text-align:right;">16 或 18</td><td>尚未计激活、临时 buffer、碎片和 checkpoint</td></tr></tbody></table><p>因此“70 亿参数 × 2 字节约 14 GB”只描述一份低精度权重，不能说明训练能否放进 24 GB 或 40 GB GPU。若按 16 字节/参数粗估，仅模型状态就约 112 GB；若是 18 字节则约 126 GB。具体实现可能融合状态、使用 FP32 梯度、延迟初始化或把状态放到 CPU，必须以实际 optimizer 和框架为准。</p><p><a href="https://www.deepspeed.ai/tutorials/zero/" target="_blank" rel="noreferrer">DeepSpeed ZeRO 教程</a>给出的阶段划分正是对这本账的拆分：Stage 1 切分优化器状态，Stage 2 再切梯度，Stage 3 再切参数。假设数据并行度为 <code>N</code>，理想下对应项目的单卡占用可除以 <code>N</code>，但 AllGather、ReduceScatter bucket 和当前层完整参数仍会形成瞬时峰值。</p><h2 id="激活为何经常成为第一大项" tabindex="-1">激活为何经常成为第一大项 <a class="header-anchor" href="#激活为何经常成为第一大项" aria-label="Permalink to “激活为何经常成为第一大项”">​</a></h2><p>自动微分在前向时保存反向需要的中间结果，包括层输入、注意力相关张量、归一化统计和非线性输入。激活规模与 micro batch、序列长度、隐藏维度和层数近似成正比；朴素注意力的某些中间量还可能随序列长度平方增长。参数量固定时，把上下文从 4K 扩到 32K，激活账本可能先于参数账本失控。</p><p>不要用“每层输出 <code>B×S×H</code>”代表整层激活。一个 Transformer 块中，Q/K/V、注意力输出、MLP 扩展维度、残差、Dropout mask 和 kernel 保存张量都可能在反向前存活。融合算子、Flash Attention、GQA、是否保存 attention matrix 会改变常数项。更可靠的方法是：先用结构公式估下界，再在目标配置上测量 <code>allocated</code> 峰值，并记录每层 saved tensors。</p><p>微批次是最直接的激活旋钮。梯度累积可以在保持全局 batch 的同时降低单次前后向的激活峰值，但会增加每个 optimizer step 的前后向次数。PP 下还要考虑同时在途的微批次：单个微批次变小不代表总保存激活一定同比下降，调度决定多少批激活会重叠驻留。</p><h2 id="激活重计算-以算力换驻留时间" tabindex="-1">激活重计算：以算力换驻留时间 <a class="header-anchor" href="#激活重计算-以算力换驻留时间" aria-label="Permalink to “激活重计算：以算力换驻留时间”">​</a></h2><p>Activation Checkpointing 只保存少量边界输入，反向需要内部中间结果时重新执行一段前向。<a href="https://docs.pytorch.org/docs/stable/checkpoint" target="_blank" rel="noreferrer">PyTorch 官方文档</a>直接将其定义为“以计算换显存”；早期论文 <a href="https://arxiv.org/abs/1604.06174" target="_blank" rel="noreferrer">Training Deep Nets with Sublinear Memory Cost</a>系统化展示了利用重计算把深网内存降到次线性量级的思路。</p><p>全量重计算简单但代价大：每层反向前都重跑完整前向。选择性重计算只对激活大而重算相对便宜的区域 checkpoint，例如注意力核心、MLP 中间激活，保留昂贵或状态敏感的结果。最优边界取决于 kernel：若某算子已经受内存带宽限制，重算可能比从 HBM 读取保存结果更划算；若是高算力利用率的巨大 GEMM，重跑成本就很真实。</p><p>重计算还有正确性约束。Checkpoint 区域若包含随机操作，必须正确保存和恢复 RNG 状态，否则 Dropout 等操作在重算时会生成不同掩码。若重算期间依赖了前向之后被改变的全局状态，反向图可能与原始前向不一致。PyTorch 文档也提醒：若 checkpoint 函数在反向重调时与前向行为不同，可能导致静默错误或异常。应对小模型做无 checkpoint 与有 checkpoint 的 loss、梯度范数和若干参数梯度对照。</p><p>DeepSpeed 的<a href="https://www.deepspeed.ai/training/" target="_blank" rel="noreferrer">训练功能说明</a>还提供激活分片、CPU checkpoint 与连续内存优化。CPU offload 可以显著降低 GPU 常驻激活，却增加设备间拷贝；只有拷贝能与计算重叠且主机带宽充足时，吞吐损失才可控。连续 buffer 解决碎片问题，但它消耗的是预留空间，不是“零成本整理”。</p>',14)),o(s,{preset:"precision"}),e[4]||(e[4]=i('<h2 id="临时张量、通信缓冲与碎片" tabindex="-1">临时张量、通信缓冲与碎片 <a class="header-anchor" href="#临时张量、通信缓冲与碎片" aria-label="Permalink to “临时张量、通信缓冲与碎片”">​</a></h2><p>训练峰值不仅由长生命周期对象决定。矩阵乘法、注意力、归一化、排序或路由 kernel 可能申请 workspace；FSDP 在某层计算前 AllGather 完整参数，DDP/ZeRO 为通信建立 bucket；梯度裁剪可能临时计算范数；保存 checkpoint 时还可能聚合完整 state dict。这些对象各自存在时间短，却可能恰好与激活或梯度峰值重叠。</p><p>分配器通常维护 reserved memory 池，已释放 tensor 对应的块未必立即归还驱动，所以 <code>nvidia-smi</code>、框架 <code>reserved</code> 和活跃 tensor 的 <code>allocated</code> 会不同。外部碎片意味着总空闲字节足够，却没有满足一次大申请的连续块。频繁变化的序列长度、不规则 MoE token 数和交替出现的长短生命周期 tensor 都会放大碎片。</p><p>正确观测至少包括：当前/峰值 allocated、当前/峰值 reserved、inactive split blocks、OOM 时请求大小、各通信 bucket 尺寸以及目标步骤的 memory snapshot。只在训练结束读取当前值会错过峰值；只看 <code>nvidia-smi</code> 又无法把缓存与活跃 tensor 分开。容量预估也应留出 runtime、NCCL、CUDA graph 和偶发长 batch 的余量，而不是把理论账本塞满物理显存。</p><h2 id="混合精度到底混合了什么" tabindex="-1">混合精度到底混合了什么 <a class="header-anchor" href="#混合精度到底混合了什么" aria-label="Permalink to “混合精度到底混合了什么”">​</a></h2><p>混合精度不是把整个模型无差别 <code>.half()</code>。线性层和卷积等算子在低精度输入上通常能使用高吞吐 Tensor Core；归约、指数、对数、Softmax、损失等对动态范围或舍入更敏感的操作常保留 FP32。PyTorch <code>torch.amp</code> 的<a href="https://docs.pytorch.org/docs/stable/amp.html" target="_blank" rel="noreferrer">官方说明</a>即按算子选择 dtype：<code>autocast</code> 决定执行精度，FP16 训练通常再配合 <code>GradScaler</code>。</p><p>三种常见格式的差异不能只用“都是 16 位”概括：</p><table tabindex="0"><thead><tr><th>格式</th><th>指数/尾数特性</th><th>训练含义</th></tr></thead><tbody><tr><td>FP32</td><td>较宽动态范围与较高精度</td><td>参考路径、主权重、敏感归约和状态常用</td></tr><tr><td>FP16</td><td>指数范围窄、尾数较 BF16 多</td><td>精度较细但容易上溢/下溢，通常需要 loss scaling</td></tr><tr><td>BF16</td><td>指数范围接近 FP32、尾数更短</td><td>较少动态范围问题，但舍入误差更大，仍非“不会溢出”</td></tr></tbody></table><p><a href="https://arxiv.org/abs/1710.03740" target="_blank" rel="noreferrer">Mixed Precision Training 论文</a>提出用 FP16 执行大量计算，同时保留必要的 FP32 信息，并通过 loss scaling 保护很小的梯度。NVIDIA 的<a href="https://docs.nvidia.com/deeplearning/performance/mixed-precision-training/index.html" target="_blank" rel="noreferrer">混合精度训练指南</a>也将低精度计算、FP32 主权重和损失缩放列为典型步骤。</p><p>FP32 主权重的理由是更新分辨率：当某次梯度更新远小于当前低精度权重的一个 ULP 时，直接加到 FP16/BF16 权重可能被舍入掉。优化器在更高精度副本上累计更新，再转换为计算权重，可保留这些小变化。是否实际保留独立主权重、梯度采用何种 dtype，应查看框架与 fused optimizer 的实现，不应套用固定字节公式。</p><h2 id="loss-scaling-保护小梯度-不是修复所有-nan" tabindex="-1">Loss Scaling：保护小梯度，不是修复所有 NaN <a class="header-anchor" href="#loss-scaling-保护小梯度-不是修复所有-nan" aria-label="Permalink to “Loss Scaling：保护小梯度，不是修复所有 NaN”">​</a></h2><p>FP16 的最小可表示范围有限，小梯度可能下溢成零。Loss scaling 在反向前把 loss 乘以尺度 <code>s</code>，使链式法则产生的梯度也乘以 <code>s</code>；在 optimizer 使用前再除以 <code>s</code>，数学更新保持不变，但中间梯度更可能落在 FP16 可表示区间。</p><p>静态尺度需要人工选择，过小保护不足，过大又会使梯度上溢。动态 <code>GradScaler</code> 会在连续若干步无 Inf/NaN 时增大尺度，检测到非有限梯度时跳过更新并降低尺度。PyTorch 文档特别指出 scale 可能降到 1 以下，且 AMP 不保证任意模型都兼容 FP16；如果 loss 或梯度持续 NaN，应检查模型范围，而不是无限调整 scaler。</p><p>Loss scaling 只能缓解低精度梯度下溢。若前向中的 logits、attention score 或指数已经溢出，放大 loss 反而无关；若学习率过大、数据异常、除零、错误 mask 或自定义 kernel 越界，也必须定位原始算子。判断顺序应是：找到首次非有限 tensor，再区分发生在前向、反向还是 optimizer step。</p><h2 id="数值稳定是一条端到端链路" tabindex="-1">数值稳定是一条端到端链路 <a class="header-anchor" href="#数值稳定是一条端到端链路" aria-label="Permalink to “数值稳定是一条端到端链路”">​</a></h2><p>浮点运算不满足实数运算中的结合律，改变归约树、设备数或 kernel 会改变加法顺序。PyTorch 的<a href="https://docs.pytorch.org/docs/stable/notes/numerical_accuracy.html" target="_blank" rel="noreferrer">数值精度说明</a>明确指出，数学上相同的浮点计算不保证逐位相同，CPU/GPU、版本与平台间也可能产生差异。因此分布式训练验证应采用误差容限、loss 趋势和任务指标，不应把 bitwise equality 当作普遍正确性条件。</p><p>常见稳定化策略都在控制中间量范围：</p><ul><li>Softmax 先减去行最大值，避免 <code>exp</code> 对大正数上溢；mask 应使用与 dtype 和 kernel 兼容的表示。</li><li><code>log(sum(exp(x)))</code> 使用 log-sum-exp 形式，避免先指数再求和的极端范围。</li><li>LayerNorm/RMSNorm 的统计和 epsilon 要在足够精度下计算；epsilon 不是越小越准确。</li><li>梯度裁剪在更新前约束异常大梯度，但它会改变优化轨迹，只能作为明确的算法配置。</li><li>归约和累加使用 FP32 能降低大量低精度项相加的误差；最终输出 dtype 与内部累加 dtype 需要分别确认。</li><li>学习率 warmup、合理初始化和归一化位置影响激活与梯度尺度，系统精度策略不能替代算法稳定性设计。</li></ul><p>出现不稳定时，应在首次异常之前布置观测：每层激活最大绝对值、均值/方差，loss 分量，缩放前后梯度范数，非有限元素计数，scaler 值与跳步次数。只在最终 loss 变成 NaN 后 dump 整个模型，通常已经丢失了第一现场。</p><h2 id="优化器状态是容量与精度的交叉点" tabindex="-1">优化器状态是容量与精度的交叉点 <a class="header-anchor" href="#优化器状态是容量与精度的交叉点" aria-label="Permalink to “优化器状态是容量与精度的交叉点”">​</a></h2><p>Adam 为每个参数维护一阶、二阶矩，状态量通常是参数本身的两倍元素数；再加主权重后，优化器相关账本往往超过低精度模型权重。Stage 1/FSDP optimizer-state sharding 因而经常是风险较低、收益明显的第一步：参数计算布局不变，只把不同参数的更新责任分给不同 DP rank。</p><p>状态切分后，checkpoint 不再是单文件完整字典。保存时若把全部分片聚合到 rank 0，主机或 GPU 峰值可能突然翻倍；分片 checkpoint 则要求恢复端理解原来的 world size、参数映射与格式。PyTorch FSDP 文档区分 full、sharded 和 local state dict，并说明 <code>FULL_SHARD</code> 下参数、梯度和优化器状态的切分与物化生命周期，见 <a href="https://docs.pytorch.org/docs/stable/fsdp.html" target="_blank" rel="noreferrer">FSDP API</a>。</p><p>把优化器 offload 到 CPU 可换取 GPU 容量，但每步要搬运梯度、参数或状态，并在 CPU 上执行更新。瓶颈可能从 HBM 变成 PCIe、主机内存带宽和 CPU 算力。应同时记录 GPU step time、CPU optimizer time、H2D/D2H 字节数和 overlap，而不是只庆祝 GPU 显存下降。</p><h2 id="一套可执行的容量规划方法" tabindex="-1">一套可执行的容量规划方法 <a class="header-anchor" href="#一套可执行的容量规划方法" aria-label="Permalink to “一套可执行的容量规划方法”">​</a></h2><ol><li><strong>固定训练语义</strong>：模型结构、序列长度、micro batch、梯度累积、精度、优化器和 checkpoint 策略必须先确定。</li><li><strong>计算模型状态下界</strong>：逐项写参数、梯度、主权重、各优化器状态的元素数与 dtype，不用模糊的“约几倍”。</li><li><strong>估计激活</strong>：按层列 saved tensors，并用目标 kernel 做单层或小层数实测；再考虑 PP 在途微批次。</li><li><strong>加入瞬时项</strong>：通信 bucket、FSDP AllGather、attention/GEMM workspace、梯度范数和 checkpoint 聚合。</li><li><strong>映射生命周期</strong>：找出前向末尾、反向开始、梯度全部就绪、optimizer step 等候选峰值，而非简单相加所有最大值。</li><li><strong>保留运行余量</strong>：覆盖分配器碎片、库上下文、数据长度抖动和版本差异。</li><li><strong>用目标配置验证</strong>：先跑数十个 warmup step，再捕获稳态峰值；只跑第一步会混入初始化与 autotune。</li></ol><p>如果超出预算，按瓶颈选择手段：模型状态大，优先 optimizer/gradient/parameter sharding；激活大，先降 micro batch、选择性重计算或 CP；瞬时 AllGather 大，调 wrap 粒度和并发预取；碎片高，稳定 shape、使用连续 buffer 或调整分配策略；不能把所有开关同时打开后再猜是谁生效。</p><h2 id="一个十三亿参数训练的显存估算案例" tabindex="-1">一个十三亿参数训练的显存估算案例 <a class="header-anchor" href="#一个十三亿参数训练的显存估算案例" aria-label="Permalink to “一个十三亿参数训练的显存估算案例”">​</a></h2><p>假设训练一个十三亿参数的稠密模型，采用 BF16 计算、FP32 主权重和 AdamW。先只计算模型状态：BF16 权重约二点六 GB，BF16 梯度约二点六 GB，FP32 主权重约五点二 GB，两个 FP32 动量合计约十点四 GB，总下界约二十点八 GB。这里的 GB 是十进制估算，监控工具若以 GiB 显示会有差异；此外尚未包含激活、临时张量和分配器缓存。</p><p>若改用八路数据并行，普通 DDP 每张卡仍保留全部二十点八 GB 状态。ZeRO Stage 1 只把主权重及两个 Adam 状态按八路切分，若实现把这十二字节每参数都归入优化器侧，则单卡模型状态可粗估为 BF16 权重二点六 GB、梯度二点六 GB，加上分片后的优化器相关状态约二点六 GB，合计约七点八 GB。Stage 2 再切梯度，可把梯度常驻部分从二点六 GB 降到约零点三二五 GB；Stage 3 连参数也切分，静态模型状态可进一步接近二十点八除以八，即约二点六 GB。</p><p>这些数字不能直接作为购卡结论。Stage 3 在当前模块计算前会 AllGather 参数，峰值还要加至少一个被物化模块、预取模块和通信 bucket；混合精度实现也可能采用 FP32 梯度或不同主权重布局。真正的预算表应同时写“静态分片值”和“峰值物化值”。假设实测每卡保存激活九 GB，当前层和预取层参数合计一点五 GB，算子 workspace 与通信缓冲三 GB，框架及安全余量四 GB，那么即使静态状态只有二点六 GB，总预算仍约二十点一 GB。</p><p>接下来做灵敏度分析。把微批次从一加到二，如果激活近似线性增长，九 GB 可能变成十八 GB，而参数状态不变；把序列长度翻倍，普通激活近似翻倍，未使用内存优化注意力时部分中间量甚至增长更快；把重计算打开，激活下降但步时上升。容量实验因此至少要扫描微批次、序列长度和重计算三维，并在每个点记录有效 token 吞吐。只报告“最大能跑 batch”会掩盖该点可能因重计算或通信而极慢。</p><h2 id="从首个异常张量定位数值故障" tabindex="-1">从首个异常张量定位数值故障 <a class="header-anchor" href="#从首个异常张量定位数值故障" aria-label="Permalink to “从首个异常张量定位数值故障”">​</a></h2><p>数值故障排查的核心是找到<strong>第一次</strong>出现异常的位置。先把一个训练 step 分成前向、缩放后反向、反缩放与裁剪、优化器更新四段，在段边界记录 loss 是否有限、梯度最大值与范数、scaler 值、参数更新前后范围。若最终参数出现 NaN，但反向梯度仍有限，问题更可能位于 optimizer、权重衰减或状态；若 loss 在前向已经非有限，调整 GradScaler 没有意义。</p><p>前向异常应从最后一个有限模块向后缩小。若 Softmax 前 attention score 已是 Inf，检查 QK 尺度、mask 和低精度乘积；若 score 有限而 Softmax 输出异常，检查是否出现整行全部被 mask、减最大值和归约精度；若归一化后异常，检查输入范围、方差计算和 epsilon。可以暂时让单个可疑模块在 FP32 执行做定位，但不应把“全模型切回 FP32 后正常”当作根因，因为它只说明故障与精度路径相关。</p><p>反向异常要区分下溢、上溢和真实梯度爆炸。大量梯度精确为零、提高 loss scale 后恢复，符合 FP16 下溢；GradScaler 连续回退且最早异常集中于某层，可能是上溢；FP32 基线同样出现快速增大的梯度范数，则更像学习率、数据或模型结构问题。梯度裁剪能阻止一次巨大更新，却会掩盖异常来源，所以调试时应同时保存裁剪前范数和触发比例。</p><p>恢复训练后才出现异常，优先比较 checkpoint 前后五类状态：模型参数、优化器一二阶矩、学习率调度步数、AMP scaler、随机数状态。若只恢复了权重而未恢复 Adam 状态，第一步更新幅度会改变；若 scaler 回到很大的初始值，可能连续发生溢出跳步；若数据游标或随机数状态改变，loss 的小幅跳变未必是数值错误。验收应在保存前记录下一批输入标识，并让恢复作业从同一批次继续，才能把恢复完整性与数据差异分开。</p><p>最后建立最小复现矩阵：相同 batch 分别运行 FP32 单卡、低精度单卡、低精度分布式三组。第一组失败说明问题不属于混合精度或集合通信；只有第二组失败说明重点检查 autocast 和 loss scaling；前两组正常而第三组失败，则检查归约 dtype、分片生命周期、不同 rank 数据以及自定义通信算子。这个分层对照比反复试学习率更快，也能避免把分布式配置错误误判成模型不稳定。</p><h2 id="稳定性验收清单" tabindex="-1">稳定性验收清单 <a class="header-anchor" href="#稳定性验收清单" aria-label="Permalink to “稳定性验收清单”">​</a></h2><ul><li>在 FP32 小规模基线上记录 loss、梯度范数、关键激活范围和任务指标。</li><li>切换 BF16/FP16 后逐项确认 autocast 区域、敏感算子 dtype、累加 dtype 与 optimizer state dtype。</li><li>FP16 记录动态 scaler 曲线、Inf/NaN 检测和跳过更新次数；持续回退意味着问题未解决。</li><li>对比开启/关闭重计算的 loss 与梯度，覆盖 Dropout 和其他随机算子。</li><li>逐步扩大 DP/TP/PP，使用容限比较而非逐位比较，并观察差异是否随 step 系统性放大。</li><li>至少做一次完整 save/resume，验证 loss 连续、学习率与 optimizer step 连续、scaler 和 RNG 状态被恢复。</li><li>报告有效 token 吞吐、峰值 allocated/reserved、重计算比例和达到目标质量的总成本，而不只报告单步速度。</li></ul><p>显存与数值从来不是两个独立议题。低精度减少字节也改变动态范围，重计算减少驻留也改变执行顺序，分片减少副本也改变归约顺序与 checkpoint 形式。最稳妥的方法不是寻找一个“最佳开关”，而是保留账本、边界和对照实验，让每次节省都能解释、每次数值偏差都能定位。</p><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li><a href="https://docs.pytorch.org/docs/stable/amp.html" target="_blank" rel="noreferrer">PyTorch：Automatic Mixed Precision</a></li><li><a href="https://docs.pytorch.org/docs/stable/checkpoint" target="_blank" rel="noreferrer">PyTorch：Activation Checkpointing</a></li><li><a href="https://docs.pytorch.org/docs/stable/notes/numerical_accuracy.html" target="_blank" rel="noreferrer">PyTorch：Numerical Accuracy</a></li><li><a href="https://docs.pytorch.org/docs/stable/fsdp.html" target="_blank" rel="noreferrer">PyTorch：FullyShardedDataParallel</a></li><li><a href="https://arxiv.org/abs/1710.03740" target="_blank" rel="noreferrer">Micikevicius et al.：Mixed Precision Training</a></li><li><a href="https://arxiv.org/abs/1604.06174" target="_blank" rel="noreferrer">Chen et al.：Training Deep Nets with Sublinear Memory Cost</a></li><li><a href="https://arxiv.org/abs/1910.02054" target="_blank" rel="noreferrer">Rajbhandari et al.：ZeRO</a></li><li><a href="https://www.deepspeed.ai/tutorials/zero/" target="_blank" rel="noreferrer">DeepSpeed：Zero Redundancy Optimizer Tutorial</a></li><li><a href="https://www.deepspeed.ai/training/" target="_blank" rel="noreferrer">DeepSpeed：Training Overview and Features</a></li><li><a href="https://docs.nvidia.com/deeplearning/performance/mixed-precision-training/index.html" target="_blank" rel="noreferrer">NVIDIA：Training With Mixed Precision</a></li></ul>',42))])}const y=n(p,[["render",h]]);export{u as __pageData,y as default};
